SELECT event_id,state,payload_digest,payload,created_at,xmin::text AS row_transaction_id, encode(sha256(convert_to(payload->>'probe','UTF8')),'hex')=payload_digest AS digest_verified, (state='blocked' AND current_attempt_id IS NULL AND attempt_count=0 AND grant_id IS NULL) AS non_dispatchable, (SELECT count(*) FROM mainbrain_api.receipts r WHERE r.event_id=e.event_id) AS ack_receipt_count, clock_timestamp() AS readback_at FROM mainbrain_api.events e WHERE event_id='L3-READBACK-20261106-0555d788-abea-4a44-b5f1-d01c5cd5487c';
